import React, { useEffect, useRef, useState } from "react";

function Generate() {
  const canvasRef = useRef();
  const containerRef = useRef();
  const [imagePaths, setImagePaths] = useState([]);
  const [isFading, setIsFading] = useState(false);
  const [effects, setEffects] = useState({
    saturation: 50,
    pixelate: 50,
  });
  const position = useRef({ x: 0, y: 0 });
  const offset = useRef({ x: 0, y: 0 });
  const isDragging = useRef(false);
  const animationRef = useRef();

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]").slice(0, 5);
    if (!stored.length) return;
    setImagePaths(stored);
    generateImage(stored);
    return () => cancelAnimationFrame(animationRef.current);
  }, []);

  const generateGrain = (ctx, width, height, intensity = 300, gamma = 1.4) => {
    const grainData = ctx.getImageData(0, 0, width, height);
    const data = grainData.data;
    for (let i = 0; i < data.length; i += 4) {
      const noise = Math.floor(Math.random() * intensity) - intensity / 2;
      data[i] = 255 * Math.pow(Math.min(255, Math.max(0, data[i] + noise)) / 255, 1 / gamma);
      data[i + 1] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 1] + noise)) / 255, 1 / gamma);
      data[i + 2] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 2] + noise)) / 255, 1 / gamma);
    }
    ctx.putImageData(grainData, 0, 0);
  };

  const applyScanlines = (ctx, width, height, gap = 3, alpha = 0.15) => {
    ctx.save();
    ctx.fillStyle = `rgba(0,0,0,${alpha})`;
    for (let y = 0; y < height; y += gap) {
      ctx.fillRect(0, y, width, 1);
    }
    ctx.restore();
  };

  const applyChromaticAberration = (ctx, width, height, offset = 2) => {
    const imgData = ctx.getImageData(0, 0, width, height);
    const data = imgData.data;
    const copy = new Uint8ClampedArray(data);

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const i = (y * width + x) * 4;

        const redIndex = ((y * width + Math.min(width - 1, x + offset)) * 4);
        const blueIndex = ((y * width + Math.max(0, x - offset)) * 4);

        data[i] = copy[redIndex];        // Red
        data[i + 2] = copy[blueIndex + 2]; // Blue
      }
    }
    ctx.putImageData(imgData, 0, 0);
  };

  const applyGlitchEffect = (ctx, width, height, lineHeight = 4, shiftAmount = 10) => {
    for (let y = 0; y < height; y += lineHeight * 4) {
      const shift = (Math.random() - 0.5) * shiftAmount;
      const imageData = ctx.getImageData(0, y, width, lineHeight);
      ctx.putImageData(imageData, shift, y);
    }
  };

  const applyPixelate = (canvas, blockSize = 12) => {
    const ctx = canvas.getContext("2d");
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;

    for (let y = 0; y < canvas.height; y += blockSize) {
      for (let x = 0; x < canvas.width; x += blockSize) {
        const i = (y * canvas.width + x) * 4;
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];

        for (let dy = 0; dy < blockSize; dy++) {
          for (let dx = 0; dx < blockSize; dx++) {
            const ii = ((y + dy) * canvas.width + (x + dx)) * 4;
            data[ii] = r;
            data[ii + 1] = g;
            data[ii + 2] = b;
          }
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas;
  };

  const thresholdImage = (canvas) => {
    const ctx = canvas.getContext("2d");
    const imageData = ctx.getImageData(0, 0, 1080, 1080);
    const data = imageData.data;

    for (let i = 0; i < data.length; i += 4) {
      const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
      const val = avg > 128 ? 255 : 0;
      data[i] = data[i + 1] = data[i + 2] = val;
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas;
  };

  const applyExclusion = (ctx, width, height, images) => {
    const baseImageData = ctx.getImageData(0, 0, width, height);
    const baseData = baseImageData.data;

    images.forEach((img, index) => {
      if (!img) return;
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = width;
      tempCanvas.height = height;
      const tempCtx = tempCanvas.getContext('2d');
      tempCtx.drawImage(img, 0, 0, width, height);
      const imgData = tempCtx.getImageData(0, 0, width, height);
      const data = imgData.data;

      for (let i = 0; i < data.length; i += 4) {
        baseData[i] = 255 - Math.abs(baseData[i] - data[i]);
        baseData[i + 1] = 255 - Math.abs(baseData[i + 1] - data[i + 1]);
        baseData[i + 2] = 255 - Math.abs(baseData[i + 2] - data[i + 2]);
      }
    });

    ctx.putImageData(baseImageData, 0, 0);
  };

  const applySobelEdgeDetection = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const sobelData = new Uint8ClampedArray(data.length);

    const sobelX = [-1, 0, 1, -2, 0, 2, -1, 0, 1];
    const sobelY = [-1, -2, -1, 0, 0, 0, 1, 2, 1];

    for (let y = 1; y < height - 1; y++) {
      for (let x = 1; x < width - 1; x++) {
        let gx = 0, gy = 0;
        let kernelIdx = 0;

        for (let ky = -1; ky <= 1; ky++) {
          for (let kx = -1; kx <= 1; kx++) {
            const pixelIdx = ((y + ky) * width + (x + kx)) * 4;
            const gray = (data[pixelIdx] + data[pixelIdx + 1] + data[pixelIdx + 2]) / 3;
            gx += gray * sobelX[kernelIdx];
            gy += gray * sobelY[kernelIdx];
            kernelIdx++;
          }
        }

        const magnitude = Math.sqrt(gx * gx + gy * gy);
        const pixelIdx = (y * width + x) * 4;
        sobelData[pixelIdx] = sobelData[pixelIdx + 1] = sobelData[pixelIdx + 2] = magnitude;
        sobelData[pixelIdx + 3] = 255;
      }
    }

    ctx.putImageData(new ImageData(sobelData, width, height), 0, 0);
  };

  const applyWaveTransform = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const tempData = new Uint8ClampedArray(data);
    const amplitude = 20;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const waveX = x + Math.sin(y * 0.05) * amplitude;
        const waveY = y + Math.cos(x * 0.05) * amplitude;

        if (waveX >= 0 && waveX < width && waveY >= 0 && waveY < height) {
          const srcIdx = (y * width + x) * 4;
          const destIdx = (Math.floor(waveY) * width + Math.floor(waveX)) * 4;

          data[destIdx] = tempData[srcIdx];
          data[destIdx + 1] = tempData[srcIdx + 1];
          data[destIdx + 2] = tempData[srcIdx + 2];
          data[destIdx + 3] = tempData[srcIdx + 3];
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const applySpiralTransform = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const tempData = new Uint8ClampedArray(data);
    const centerX = width / 2;
    const centerY = height / 2;
    const density = 0.01;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const dx = x - centerX;
        const dy = y - centerY;
        const angle = Math.atan2(dy, dx);
        const radius = Math.sqrt(dx * dx + dy * dy);

        const spiralX = centerX + radius * Math.cos(angle + radius * density);
        const spiralY = centerY + radius * Math.sin(angle + radius * density);

        if (spiralX >= 0 && spiralX < width && spiralY >= 0 && spiralY < height) {
          const srcIdx = (y * width + x) * 4;
          const destIdx = (Math.floor(spiralY) * width + Math.floor(spiralX)) * 4;

          data[destIdx] = tempData[srcIdx];
          data[destIdx + 1] = tempData[srcIdx + 1];
          data[destIdx + 2] = tempData[srcIdx + 2];
          data[destIdx + 3] = tempData[srcIdx + 3];
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const applyTrailEffect = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const tempData = new Uint8ClampedArray(data);
    const trailLength = 10;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const idx = (y * width + x) * 4;
        let r = 0, g = 0, b = 0, a = 0;

        for (let i = 0; i < trailLength; i++) {
          const offset = i * 4;
          const alpha = 1 - (i / trailLength);
          r += tempData[idx + offset] * alpha;
          g += tempData[idx + offset + 1] * alpha;
          b += tempData[idx + offset + 2] * alpha;
          a += tempData[idx + offset + 3] * alpha;
        }

        data[idx] = r / trailLength;
        data[idx + 1] = g / trailLength;
        data[idx + 2] = b / trailLength;
        data[idx + 3] = a / trailLength;
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const applyRippleEffect = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const tempData = new Uint8ClampedArray(data);
    const centerX = width / 2;
    const centerY = height / 2;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const dx = x - centerX;
        const dy = y - centerY;
        const distance = Math.sqrt(dx * dx + dy * dy);
        const angle = Math.atan2(dy, dx);

        const rippleX = x + Math.cos(angle) * Math.sin(distance * 0.1) * 10;
        const rippleY = y + Math.sin(angle) * Math.sin(distance * 0.1) * 10;

        if (rippleX >= 0 && rippleX < width && rippleY >= 0 && rippleY < height) {
          const srcIdx = (y * width + x) * 4;
          const destIdx = (Math.floor(rippleY) * width + Math.floor(rippleX)) * 4;

          data[destIdx] = tempData[srcIdx];
          data[destIdx + 1] = tempData[srcIdx + 1];
          data[destIdx + 2] = tempData[srcIdx + 2];
          data[destIdx + 3] = tempData[srcIdx + 3];
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const generateImage = (imagePaths) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const loadImage = (src) =>
      new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => resolve(img);
        img.src = src;
      });

    Promise.all(imagePaths.map(loadImage)).then((images) => {
      // Step 1: Stack and apply exclusion
      applyExclusion(ctx, canvas.width, canvas.height, images);

      // Step 2: Edge detection
      applySobelEdgeDetection(ctx, canvas.width, canvas.height);

      // Step 3: Wave transform
      applyWaveTransform(ctx, canvas.width, canvas.height);

      // Step 4: Spiral composition
      applySpiralTransform(ctx, canvas.width, canvas.height);

      // Step 5: Trail effect
      applyTrailEffect(ctx, canvas.width, canvas.height);

      // Step 6: Final enhancements
      applyRippleEffect(ctx, canvas.width, canvas.height);
      applyChromaticAberration(ctx, canvas.width, canvas.height);

      // Add timestamp
      const now = new Date();
      const timestamp = now.toLocaleString();
      ctx.save();
      ctx.translate(canvas.width - 30, canvas.height - 20);
      ctx.rotate(-Math.PI / 2);
      ctx.font = '16px Arial';
      ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
      ctx.fillText(timestamp, 0, 0);
      ctx.restore();

      // Store the base image for post-processing
      const baseImage = ctx.getImageData(0, 0, canvas.width, canvas.height);
      applyPostProcessing(baseImage);
    });
  };

  const applyPostProcessing = (baseImage) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    // Apply base image
    ctx.putImageData(baseImage, 0, 0);

    // Apply pixelation if enabled
    if (effects.pixelate > 0) {
      applyPixelate(canvas, Math.floor((effects.pixelate / 100) * 20));
    }

    // Apply saturation adjustment
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;
    const saturation = effects.saturation / 50; // 0-2 range

    for (let i = 0; i < data.length; i += 4) {
      const gray = 0.2989 * data[i] + 0.5870 * data[i + 1] + 0.1140 * data[i + 2];
      data[i] = gray + (data[i] - gray) * saturation;
      data[i + 1] = gray + (data[i + 1] - gray) * saturation;
      data[i + 2] = gray + (data[i + 2] - gray) * saturation;
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const handleEffectChange = (effect, value) => {
    setEffects(prev => ({ ...prev, [effect]: value }));
    // Reapply post-processing effects
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const baseImage = ctx.getImageData(0, 0, canvas.width, canvas.height);
    applyPostProcessing(baseImage);
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      generateImage(imagePaths);
      setIsFading(false);
    }, 300);
  };

  return (
    <div
      ref={containerRef}
      style={{
        width: "100vw",
        height: "100vh",
        overflow: "hidden",
        position: "relative",
        touchAction: "none",
        cursor: isDragging.current ? "grabbing" : "grab",
        background: "#000",
      }}
    >
      <div style={{
  position: "absolute",
  top: 20,
  left: 20,
  background: "rgba(255,255,255,0.9)",
  padding: "10px 15px",
  borderRadius: "10px",
  zIndex: 10
}}>
  <label>
    <input
      type="checkbox"
      checked={effects.grain}
      onChange={() => setEffects(prev => ({ ...prev, grain: !prev.grain }))}
    /> Grain
  </label>
  <br />
  <label>
    <input
      type="checkbox"
      checked={effects.scanlines}
      onChange={() => setEffects(prev => ({ ...prev, scanlines: !prev.scanlines }))}
    /> Scanlines
  </label>
  <br />
  <label>
    <input
      type="checkbox"
      checked={effects.aberration}
      onChange={() => setEffects(prev => ({ ...prev, aberration: !prev.aberration }))}
    /> Chromatic Aberration
  </label>
  <br />
  <label>
    <input
      type="checkbox"
      checked={effects.glitch}
      onChange={() => setEffects(prev => ({ ...prev, glitch: !prev.glitch }))}
    /> Glitch
  </label>
</div>


      <canvas
        ref={canvasRef}
        width={1080}
        height={1080}
        style={{
          display: "block",
          margin: "0 auto",
          opacity: isFading ? 0.2 : 1,
          transition: "opacity 0.3s ease",
        }}
      />
<div style={{ position: "fixed", top: 20, right: 20, display: "flex", gap: "12px", zIndex: 10 }}>
  <button
    onClick={handleRegenerate}
    style={{
      padding: "8px 16px",
      backgroundColor: "#FFD666",
      border: "none",
      borderRadius: "8px",
      cursor: "pointer",
      fontWeight: "bold",
    }}
  >
    Regenerate
  </button>
  <button
    onClick={handleDownload}
    style={{
      padding: "8px 16px",
      backgroundColor: "#333",
      color: "#fff",
      border: "none",
      borderRadius: "8px",
      cursor: "pointer",
      fontWeight: "bold",
    }}
  >
    Download
  </button>
</div>
    </div>
  );
}

export default Generate;
